using System;

public struct Quote
{
    public string Id;
    public string Text;
    public string Author;
}

public static class ItalianQuotes
{
    public static readonly Quote[] Quotes = new Quote[]
    {
        new Quote { Id = "https://it.wikiquote.org/wiki/Joan_Cusack", Text = "La famiglia è tutto. Ecco perché amo Toy Story 3, perché le persone che li circondano è ciò che rappresentano. Senza la famiglia niente ha senso per me.", Author = "Joan Cusack" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Cvetan_Todorov", Text = "L'Europa resta forse la parte del pianeta con la più forte concentrazione di diverse identità nazionali ed etniche. Si può pensare che storicamente questa è già stata una delle fonti del dinamismo europeo.", Author = "Cvetan Todorov" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Margaret_Dumont", Text = "Devi formare il tuo uomo, ma mai superarlo, mai rubargli le risate.", Author = "Margaret Dumont" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Solaris_%28film_1972%29", Text = "Comunque sei stato fortunato, comunque quella donna fa parte di te, del tuo passato. Pensa se invece ti fosse apparso qualcuno che non avevi mai conosciuto, ma solo pensato, immaginato. (Dottor Snaut)", Author = "Solaris (film 1972)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Juan_Carlos_I_di_Spagna", Text = "[Durante la chiusura del vertice iberoamericano di Santiago del Cile, 10 novembre 2007, al presidente venezuelano Hugo Chávez] Perché non taci?", Author = "Juan Carlos I di Spagna" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Maial_College", Text = "Cena per due: io e te, vestiti facoltativi. (Van Wilder)", Author = "Maial College" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Bianca_Berlinguer", Text = "Devo dire che per dirigere un telegiornale o un talk show c'è bisogno di avere anche qualche nozione di psicologia.", Author = "Bianca Berlinguer" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Romulani", Text = "– Romulani? Ho letto qualcosa quando ero con Daniels.– E che cosa hai scoperto?– Non molto. Solo il nome. (Campo minato)", Author = "Romulani" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Pievano_Arlotto", Text = "Chi scrive non tiene a memoria. (Facezia sesta fatta per il Piovano dinanzi al re Alfonso in Neapoli[1])", Author = "Pievano Arlotto" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Monica_Bellucci", Text = "È brutto vedere il corpo decadere senza che tu gli abbia dato il permesso. (citata in Corriere della Sera, 6 marzo 1996)", Author = "Monica Bellucci" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Fury_%28fumetto%29", Text = "Mi chiamo Nick Fury. Dal '44 ho un proiettile piantato in testa. A quanto pare non posso morire e invecchio molto lentamente. Combatto e scopo come un indemoniato. Mi abbuffo di guerra come fosse zucchero. (Nick Fury)", Author = "Fury (fumetto)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Didier_Daeninckx", Text = "Non passa mese, al mondo, senza che uno scrittore si trovi di fronte alla minaccia del silenzio. Una lotta costantemente rinnovata. La letteratura inventa sempre nuovi spazi, nuovi territori e i fabbricanti di confini e passaporti ancora non si adattano a questa crescita nel mondo. Lo limitano.", Author = "Didier Daeninckx" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Johann_Adolph_Scheibe", Text = "Le composizioni di Johann Sebastian Bach sono prive di bellezza, di armonia e di chiarezza di melodia. (da Der critische Musikus, Amburgo, 14 maggio 1737)", Author = "Johann Adolph Scheibe" },
        new Quote { Id = "https://it.wikiquote.org/wiki/I_Fantastici_4_%28film%29", Text = "[A Reed Richards] Non cambi mai. Sempre teso ad afferrare le stelle, a caricarti del peso del mondo. Ma con i sogni non ci paghi le bollette. (Victor Von Doom)", Author = "I Fantastici 4 (film)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Radical_chic", Text = "Il radical-chic è un reazionario che dà del reazionario a chi non sputa nel piatto in cui mangia. (Roberto Gervaso)", Author = "Radical chic" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Angel%27s_Friends", Text = "Il cuore è come un labirinto misterioso, e spesso i labirinti sono tortuosi... (Episodio 2, L'osservatore)", Author = "Angel's Friends" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Alexandre_Koj%C3%A8ve", Text = "Alexandre Kojève, che pure tenne una conferenza al Collège su Les conceptions hégéliennes, aveva osservato ironicamente che il programma di Bataille e Caillois era paragonabile al tentativo di un prestigiatore di credere alla magia attraverso i propri trucchi. (Carlo Ginzburg)", Author = "Alexandre Kojève" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Albus_Silente", Text = "Affiderei ad Hagrid la mia stessa vita!", Author = "Albus Silente" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Daylight_Robbery_-_Un_Colpo_British_Style", Text = "Se volete che vada liscia, dovete parlare meno e ascoltare di più. (Matty)", Author = "Daylight Robbery - Un Colpo British Style" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Giovan_Battista_Andreini", Text = "Le Commedie di Giambatista Andreini meritano e aspettano uno studio, tanto quanto non lo meritano e non lo aspettano le sue opere d'infelicissima epica religiosa, le turgide espansioni del suo affetto per i Santi e per i Beati. (Adolfo Bartoli)", Author = "Giovan Battista Andreini" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Mathurin_R%C3%A9gnier", Text = "Les fous sont, aux échecs, le plus proches des rois.", Author = "Mathurin Régnier" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Dracula_%28film_1931_Browning%29", Text = "Noi gente di montagna siamo convinti che al castello lassù ci siano i vampiri: Dracula e le sue mogli. Le signore prendono le forme di lupi e pipistrelli, e di notte lasciano le loro bare e vanno a cibarsi del sangue di noi vivi. (Oste)", Author = "Dracula (film 1931 Browning)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Rocketman_%28film_2019%29", Text = "Io volevo essere un altro. (Giovane Elton)", Author = "Rocketman (film 2019)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Noe_Zhordania", Text = "A chi non sia stato in Georgia è difficile immaginare l'autorità di cui gode Noè Giordania.", Author = "Noe Zhordania" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Mercanti_di_Liquore", Text = "Il viaggiatore viaggia solo e non lo fa per tornare contento, lui viaggia perché di mestiere ha scelto il mestiere di vento. (da Il viaggiatore)", Author = "Mercanti di Liquore" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Andr%C3%A9_Th%C3%A9rive", Text = "[...] secondo le parole di Talleyrand, il tradimento è una questione di date [...].", Author = "André Thérive" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Bound_-_Torbido_inganno", Text = "Mi sorprendono sempre tantissimo le persone che sanno usare bene le mani. Mio padre era così, non compravamo mai niente di nuovo: quando qualcosa si rompeva noi lo chiamavamo, lui arrivava, l'apriva, guardava, armeggiava un po' e l'aggiustava. Le sue mani erano magiche. (Violet)", Author = "Bound - Torbido inganno" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Uomo_bianco%2C_tu_vivrai%21", Text = "Tutti gli uomini sono uguali, eccetto che nelle mance. (Edie)", Author = "Uomo bianco, tu vivrai!" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Cappone", Text = "A chi ti dà il cappone, dagli la coscia e l'alone.", Author = "Cappone" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Manuela_Arcuri", Text = "In effetti ho sempre amato recitare e devo dire che sono estremamente curiosa di esplorare un po' tutti i settori dello spettacolo: fotoromanzi, televisione, cinema.", Author = "Manuela Arcuri" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Andrea_Camilleri", Text = "Come fa uno a farisi capace che il tempo passa, e lo cangia, se tutti i jorni e tutte le notti non fa altro che ripetiri squasi meccanicamenti gli stissi gesti e diri le stisse paroli? (da Un giro in giostra, in Gran Circo Taddei e altre storie di Vigàta, Sellerio editore, Palermo, 2011, p. 235)", Author = "Andrea Camilleri" },
        new Quote { Id = "https://it.wikiquote.org/wiki/John_Kenneth_Galbraith", Text = "In economia, speranza e fede coesistono con grandi pretese scientifiche e un profondo desiderio di rispettabilità.", Author = "John Kenneth Galbraith" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Il_buco_%28film_2019%29", Text = "Parlare mi affatica. Soprattutto quando fornisco più informazioni di quelle che ricevo. (Trimagasi)", Author = "Il buco (film 2019)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Georg_Philipp_Telemann", Text = "Hendel diceva di lui, che scriveva un pezzo di musica a otto parti colla stessa facilità con cui un altro scriverebbe una lettera. (Giuseppe Bertini (compositore)", Author = "Georg Philipp Telemann" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Jamie_Foxx", Text = "Non concentrarti sulla luce degli altri e dimentica la tua lucentezza. Tutti sono così concentrati su ciò che fanno gli altri - Oh, guardalo mentre fa questo e guarda quello - che dimenticano quello che stanno facendo loro stessi.", Author = "Jamie Foxx" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Fruttero", Text = "La vecchiaia è un aggiustamento continuo con cacciavite e chiave inglese. Tiri avanti.", Author = "Carlo Fruttero" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Megan_Marie_Hart", Text = "La storia ebraica è piena di sofferenze e di terribili dolori. Ma è anche pieno di immensa gioia.", Author = "Megan Marie Hart" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Supergirl", Text = "Solo perché è un sacco carino, non significa che possiamo fidarci di un Brainiac! (Justice League Unlimited)", Author = "Supergirl" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Stefano_Farina", Text = "Stefano, per ben otto stagioni, ci ha cresciuto a bastone, tanto, e carota, un po' meno. Era molto esigente, ma per il bene dei suoi ragazzi. (Juan Luca Sacchi)", Author = "Stefano Farina" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Margaret_Deland", Text = "[...] l'abnegazione, se contraria al buon senso, non è tanto una virtù quanto un vizio spirituale!", Author = "Margaret Deland" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Dittatura_del_proletariato", Text = "La dittatura del proletariato, periodo di transizione verso il comunismo, istituirà per la prima volta una democrazia per il popolo, per la maggioranza, accanto alla repressione necessaria della minoranza, degli sfruttatori.", Author = "Dittatura del proletariato" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Dario_Bernazza", Text = "Il luogo comune sa avere tutta l'apparenza della verità tanto che chi lo mette in dubbio viene molto spesso considerato più uno stravagante che un uomo sensato, più un esibizionista che una persona seria.", Author = "Dario Bernazza" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Castigo", Text = "Benedetto chi si castiga da se stesso.", Author = "Castigo" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Aprile_%28film%29", Text = "Un capitolo del mio documentario sull'Italia è dedicato al giornalismo. Comincio subito a tagliare e ritagliare [...] Perché la satira non ha padroni, perciò sta bene sotto ogni padrone. Insomma, un unico grande giornale. (Nanni)", Author = "Aprile (film)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Nobile_Contrada_dell%27Aquila", Text = "Con le unghie e con il rostro", Author = "Nobile Contrada dell'Aquila" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Marty%2C_vita_di_un_timido", Text = "Ho cercato ragazze tutti i sabati sera della mia vita, ormai ho trentaquattro anni, sono stufo di cercarle, voglio trovarne una! (Marty)", Author = "Marty, vita di un timido" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Mary_Simon", Text = "La tua persona ci ricorda ogni giorno che la vera leadership si dimostra non tanto con onori o distinzioni, ma con quello che si fa per gli altri intorno a noi. Si misura nell'abilità di costruire un futuro brillante per tutti, non solo per pochi fortunati. (Justin Trudeau)", Author = "Mary Simon" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Deneve", Text = "Chi fa inutile sfoggio dei muscoli al di fuori delle situazioni di combattimento non è altro che una nullità di scarse vedute.", Author = "Deneve" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Johnny", Text = "Johnny è un nome così facile da dimenticare. E così difficile da ricordare. (Gilda)", Author = "Johnny" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Il_bell%27Antonio", Text = "Comunque ho il diabete. Mi hanno trovato più zucchero che un frutto candito. (Alfio)", Author = "Il bell'Antonio" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Jan_Narveson", Text = "Ogni essere razionale cerca di massimizzare la propria utilità, quale che possa essere, cioè di soddisfare i propri desideri, interessi, ecc.", Author = "Jan Narveson" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Papa_Urbano_VIII", Text = "Lilium et rosa. (Malachia di Armagh)", Author = "Papa Urbano VIII" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Mario_Cipollini", Text = "La nuova generazione [di ciclisti] è divenuta troppo conformista.", Author = "Mario Cipollini" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Claudia_Schiffer", Text = "Claudia Schiffer, donna forte, ma di grande dolcezza. (Valentino)", Author = "Claudia Schiffer" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Balla_coi_lupi", Text = "Stavo giusto pensando che di tutti i sentieri importanti della vita, ce n'è uno più importante degli altri. È il sentiero di un vero essere umano. (Uccello Scalciante)", Author = "Balla coi lupi" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Liturgia", Text = "Di ben poca utilità saranno le cerimonie più belle o le associazioni più fiorenti, se non sono volte ad educare gli uomini alla maturità cristiana. (Presbyterorum Ordinis)", Author = "Liturgia" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Edith_Stein", Text = "Bisogna considerarsi davvero uno strumento e soprattutto ritenere le forze con cui si lavora (nel nostro caso l'intelletto) qualcosa che usiamo non noi, ma Dio in noi.", Author = "Edith Stein" },
        new Quote { Id = "https://it.wikiquote.org/wiki/%C3%89mile-Auguste_Chartier", Text = "Che i cittadini diano più volentieri la loro vita che il loro denaro, ecco un paradosso piuttosto forte.", Author = "Émile-Auguste Chartier" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Gianpaolo_Ormezzano", Text = "Il suo calcio era stellare ma geometrico, non magico. [...] Molto semplicemente si riteneva il migliore del mondo nel suo ruolo (mezzala, si diceva) e non solo. Provvisto poi del tiro più fulminante del pianeta.", Author = "Gianpaolo Ormezzano" },
        new Quote { Id = "https://it.wikiquote.org/wiki/E.R._-_Medici_in_prima_linea", Text = "Peter Benton: Abbiamo qualcuno da cucire?Haleh Adams: E io che ne so?Peter Benton: Sai, la cosa bella qui è lo spirito di cameratismo, tutti smaniano per aiutarsi l'un l'altro!", Author = "E.R. - Medici in prima linea" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Hellraiser%3A_Hellseeker", Text = "Quale delle due cose più eccitanti al tuo giudizio, Trevor? Il dolore o il piacere? Personalmente, è il dolore che prediligo. (Pinhead)", Author = "Hellraiser: Hellseeker" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Jean-Luc_Marion", Text = "[Cristo] fa lasciando dire e dice lasciando fare.", Author = "Jean-Luc Marion" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Jeffrey_Moussaieff_Masson", Text = "Certo, di tanto in tanto gli scimpanzé adottano comportamenti da predatori, ma i gorilla non lo fanno mai. (p. 18)", Author = "Jeffrey Moussaieff Masson" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Un_posto_al_sole_%28film%29", Text = "Ogni volta che mi lasci è come se fosse un addio. Dimmi, è perché non puoi vivere senza di me? (Alice)", Author = "Un posto al sole (film)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Jared_Leto", Text = "Non seguire un sentiero, createne uno tuo.", Author = "Jared Leto" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Johannes_Gutenberg", Text = "Attraversiamo una trasformazione paragonabile a quella vissuta dagli esseri umani quando Gutenberg ha inventato la stampa. Con la riproduzione meccanica della Bibbia è arrivata l'epoca della secolarizzazione del sapere e dell'automatizzazione della produzione. (Paul B. Preciado)", Author = "Johannes Gutenberg" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Faina", Text = "È temuta da tutti i nostri contadini i quali sanno che se entra in un pollaio inebriata di sangue sgozza tutti gli animali che trova lasciando per lo più i loro corpi intatti e rosicchiando solo il collo ed il cranio per mangiare il cervello.", Author = "Faina" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Hugh_Jackman", Text = "C'è qualcosa da amare sia nella commedia sia nel dramma. Sarebbe bello riuscire a vederla così anche nella vita: esiste sempre una dolcezza che va oltre la situazione del momento.", Author = "Hugh Jackman" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Madame_de_S%C3%A9vign%C3%A9", Text = "Madame de Sévigné sarà sempre un modello per il fascino e la grazia che promanano dalla sua opera; ma, quando se ne è letto molto, non resta gran che. È come le uova frullate che possono venir mangiate a sazietà senza riempire lo stomaco. (Napoleone Bonaparte)", Author = "Madame de Sévigné" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Daniela_Farnese", Text = "Siamo una generazione figlia di Sex & the City ma praticamente nessuna di noi, soprattutto a 30 anni, ha una vita così, né centinaia di scarpe nell'armadio, un lavoro sempre appagante e avventure eccitanti.", Author = "Daniela Farnese" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Attore", Text = "A poco a poco si è venuta ad insinuare un'idea mercantile di questa professione non più legata a un'idea di cultura ma esattamente come avviene per un qualsiasi prodotto sottoposto alle leggi del mercato. (Lino Capolicchio)", Author = "Attore" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Glenda_Jackson", Text = "Tutti i registi hanno il loro approccio al lavoro che stanno facendo. Devi seguirlo, fino a un certo punto. Ad ogni modo, come in tutte le produzioni, è quando reciti, quando hai un pubblico, che sai davvero come va - e il regista non c'è!", Author = "Glenda Jackson" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Ganso", Text = "Non corre e se di mestiere facesse il cacciatore di lumache rimarrebbe disoccupato a vita. (Franco Rossi)", Author = "Ganso" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Troy_Bayliss", Text = "Portimao è una grande pista, molto impegnativa visti i numerosi scollinamenti e curve cieche. A tutti i piloti piace girarci ed una volta memorizzato è molto divertente.", Author = "Troy Bayliss" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Bruno_Lauzi", Text = "Genova, si sa, è molto conservatrice, una faccia nuova sconvolge antichi equilibri, espone al rischio di rimettere in discussione le proprie abitudini. (p. 15)", Author = "Bruno Lauzi" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Valentine_Demy", Text = "Ho sempre avuto il caschetto [...]. A Firenze c'era questo parrucchiere, Peppino Nobile, che appena mi vide disse: Te devi farti i capelli alla Rosa Fumetto, stile 'Valentina' di Crepax e da lì è rimasto, tanto che feci un servizio fotografico su Playmen come 'Valentina' di Crepax, appunto.", Author = "Valentine Demy" },
        new Quote { Id = "https://it.wikiquote.org/wiki/I_Simpson_%28terza_stagione%29", Text = "Io non sono un dentista. (Frase alla lavagna)", Author = "I Simpson (terza stagione)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Tonino_Zugarelli", Text = "Io sono cresciuto a Ponte Milvio, Tor di Quinto. Che non era come adesso, ora ci sono i locali; negli anni Sessanta trovavi solo il tizio che vendeva le cozze col limone e i cocomeri d'estate.", Author = "Tonino Zugarelli" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Raat_Akeli_Hai", Text = "Credo che una compagna di vita sia una persona con cui ti piace vivere, con cui vai d'accordo, non qualcuno che il mondo approva. Le apparenze possono essere ingannevoli. (Sarita)", Author = "Raat Akeli Hai" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Castit%C3%A0", Text = "Abbandonai l'idea di diventar prete proprio quando scappai con una canzonettista, a vent'anni. Ma che ci vuol fare: io, quell'affare della castità, non lo capisco. Lo trovo così disumano, innaturale. (Totò)", Author = "Castità" },
        new Quote { Id = "https://it.wikiquote.org/wiki/La_Mecca", Text = "Alla Mecca, i padri si sentono pronti a rinunciare ai propri figli.", Author = "La Mecca" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Vittoria_Ceretti", Text = "Ci sono momenti in cui ho bisogno di non sentire e vedere nessuno, di non viaggiare per due settimane, però non ho mai pensato di smettere, forse perché di fronte a ogni proposta ho saputo scegliere cosa fosse meglio per me, privilegiando il compleanno di mia mamma o un anniversario importante.", Author = "Vittoria Ceretti" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Adriano", Text = "Animula, vagula, blandula, | Hospes, comesque corporis, | Quæ nunc abibis in loca | Pallidula, rigida, nudula | Nec, ut soles, dabis iocos.", Author = "Adriano" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Peter_Dinklage", Text = "Amo gli animali, tutti gli animali. Non ferirei un gatto o un cane – o un pollo o una mucca. E non chiederei a qualcun altro di farlo per me. Ecco perché sono vegetariano.", Author = "Peter Dinklage" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Caligola_-_Follia_del_potere", Text = "Vai, Incitatus, ah! Vai, al galoppo! Vai, Incitatus! Così, vai, ah! (Caligola, al proprio cavallo)", Author = "Caligola - Follia del potere" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Amici%2C_amanti_e...", Text = "Non riesco a concentrarmi sui miei porno con tutto questo sesso vero intorno a me! (Eli)", Author = "Amici, amanti e..." },
        new Quote { Id = "https://it.wikiquote.org/wiki/Robert_B._Leighton", Text = "Con il suo intelletto indagatore, cercava di spiegare ogni effetto strano che si possa osservare in natura. (Gerald Neugebauer)", Author = "Robert B. Leighton" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Trittolemo", Text = "Si dice che Trittolemo abbia dato delle leggi agli Ateniesi, e Senocrate afferma che tre di queste leggi sono ancora oggi in vigore a Eleusi: onorare i genitori, glorificare gli dèi con i vegetali, non fare del male agli animali. (Ermippo di Smirne)", Author = "Trittolemo" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Le_sue_sculture_vivono_a_Oslo", Text = "Da ogni parte del mondo vengono ad ammirare questo insolito museo [Parco Vigeland], monumento imperituro alla visione poetica e all'energia creatrice dell'uomo che ha dato vita a più opere d'arte di qualsiasi altro scultore: Gustav Vigeland.", Author = "Le sue sculture vivono a Oslo" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Mao_Zedong", Text = "Grande è la confusione sotto il cielo. La situazione è eccellente.", Author = "Mao Zedong" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Marguerite_Yourcenar", Text = "Ci si crede puri finché si disprezza quel che non si desidera.", Author = "Marguerite Yourcenar" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Il_pap%27occhio", Text = "Pronto, mamma? Indovina chi sono? (Roberto Benigni)", Author = "Il pap'occhio" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Detective_Conan%3A_La_strategia_degli_abissi", Text = "Voglio fare un brindisi a questa bella crociera e a tutti gli amici che sono qui con me, e alla vittoria di Ran al torneo regionale di Karate. (Sonoko)", Author = "Detective Conan: La strategia degli abissi" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Alessandra_Mussolini", Text = "Non è un problema di destra e di sinistra. I voltagabbana vanno dove c'è il potere.", Author = "Alessandra Mussolini" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Daveed_Diggs", Text = "Credo che sia importante ricordare, come esseri umani, che tu possa innescare un notevole cambiamento già solo dal modo in cui tratti una singola persona.", Author = "Daveed Diggs" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Hugh_Grant", Text = "Luna di fiele (1992)", Author = "Hugh Grant" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Valerij_Jakovlevi%C4%8D_Brjusov", Text = "Com'è triste, fredda, giusta e nello stesso tempo toccante, la critica delle mie poesie fatta da Brjusov. Tra le righe si può leggere: Beh, allora, amico mio, ti annoi? Vuoi prendere l'uccello azzurro per la coda? (Aleksandr Aleksandrovič Blok)", Author = "Valerij Jakovlevič Brjusov" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Kader_Abdolah", Text = "Il bazar è una città nella città; un'area chiusa cui si può accedere da diverse porte. Un dedalo di strade coperte da tetti a forma di cupola. Centinaia di piccoli negozi addossati l'un all'altro. (p. 22)", Author = "Kader Abdolah" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Unthinkable", Text = "Noi abbiamo paura, loro no. Noi dubitiamo, loro credono. (H)", Author = "Unthinkable" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Cher", Text = "Mi piace avere dei fidanzati. Una ragazza può aspettare che l'uomo giusto arrivi – ma non vuol dire che nel frattempo non possa divertirsi un sacco con tutti quelli sbagliati.", Author = "Cher" }
    };
